script:
setTimeout(function () {

  var root = root_element;
  var currentPeriod = 'this_month';
  var dashData = {};
  var THEME_KEY = 'jagdamba_acct_dash_theme';

  var q  = function (s) { return root.querySelector(s); };
  var qa = function (s) { return root.querySelectorAll(s); };

  var getDashEl = function () { return q('#acAcctDashboard') || root; };

  var applyTheme = function (t) {
    if (t === 'dark') getDashEl().classList.add('dark');
    else getDashEl().classList.remove('dark');
  };
  var toggleTheme = function () {
    var isDark = getDashEl().classList.contains('dark');
    var next = isDark ? 'light' : 'dark';
    applyTheme(next);
    try { localStorage.setItem(THEME_KEY, next); } catch (e) {}
  };
  var loadTheme = function () {
    try {
      var saved = localStorage.getItem(THEME_KEY);
      if (saved) { applyTheme(saved); return; }
    } catch (e) {}
    applyTheme('light');
  };

  var setText = function (id, v) {
    var el = q('#' + id);
    if (el) el.textContent = (v !== null && v !== undefined) ? v : '—';
  };

  var fmt = function (val) {
    var num = parseFloat(val) || 0;
    var neg = num < 0;
    num = Math.abs(num);
    var out;
    if (num >= 1000000) out = (num / 1000000).toFixed(2) + 'M';
    else if (num >= 1000) out = (num / 1000).toFixed(1) + 'K';
    else out = num.toLocaleString('en-AE', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    return (neg ? '-' : '') + out;
  };

  var setDate = function () {
    var el = q('#acDate');
    if (el) el.textContent = new Date().toLocaleDateString('en-US', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric' });
  };

  var setLoading = function (on) {
    var ids = ['ac-revenue', 'ac-expense', 'ac-profit', 'ac-bankcash', 'ac-receivable', 'ac-payable'];
    ids.forEach(function (id) {
      var el = q('#' + id);
      if (!el) return;
      if (on) { el.textContent = '…'; el.classList.add('ac-pulse'); }
      else el.classList.remove('ac-pulse');
    });
  };

  var populateKPIs = function (d) {
    var k = d.kpis || {};
    setText('ac-revenue', fmt(k.total_revenue));
    setText('ac-expense', fmt(k.total_expense));
    var profitEl = q('#ac-profit');
    if (profitEl) {
      profitEl.textContent = fmt(k.net_profit);
      profitEl.style.color = (k.net_profit >= 0) ? 'var(--c-emerald)' : 'var(--c-rose)';
    }
    setText('ac-margin', 'Margin ' + (k.margin_pct || 0) + '%');
    setText('ac-bankcash', fmt(k.bank_cash_balance));
    setText('ac-receivable', fmt(k.accounts_receivable));
    setText('ac-receivable-sub', (k.overdue_receivable_count || 0) + ' overdue');
    setText('ac-payable', fmt(k.accounts_payable));
    setText('ac-payable-sub', (k.overdue_payable_count || 0) + ' overdue');
    setText('acPeriodLabel', d.period_label || '');
  };

  var populateTrend = function (rows) {
    var el = q('#ac-trend-chart');
    if (!el) return;
    if (!rows || !rows.length) { el.innerHTML = '<div class="ac-loader">No data</div>'; return; }
    var max = 0;
    rows.forEach(function (r) {
      max = Math.max(max, parseFloat(r.income) || 0, parseFloat(r.expense) || 0);
    });
    el.innerHTML = rows.map(function (r) {
      var incH = max > 0 ? Math.round((parseFloat(r.income) || 0) / max * 170) : 2;
      var expH = max > 0 ? Math.round((parseFloat(r.expense) || 0) / max * 170) : 2;
      return '<div class="ac-trend-col" title="' + r.month + ': Income ' + fmt(r.income) + ' · Expense ' + fmt(r.expense) + '">' +
        '<div class="ac-trend-bars">' +
          '<div class="ac-trend-bar income" style="height:' + incH + 'px"></div>' +
          '<div class="ac-trend-bar expense" style="height:' + expH + 'px"></div>' +
        '</div>' +
        '<span class="ac-trend-month">' + r.month + '</span>' +
      '</div>';
    }).join('');
  };

  var populateCategoryList = function (containerId, rows, colorVar) {
    var el = q('#' + containerId);
    if (!el) return;
    if (!rows || !rows.length) { el.innerHTML = '<div class="ac-loader">No data for this period</div>'; return; }
    var max = Math.max.apply(null, rows.map(function (r) { return parseFloat(r.total) || 0; }));
    el.innerHTML = rows.map(function (r) {
      var pct = max > 0 ? Math.round((parseFloat(r.total) || 0) / max * 100) : 0;
      return '<div class="ac-cat-row" data-account="' + r.account + '">' +
        '<span class="ac-cat-name">' + (r.account_name || r.account) + '</span>' +
        '<div class="ac-cat-bar-wrap"><div class="ac-cat-bar" style="width:' + pct + '%;background:' + colorVar + '"></div></div>' +
        '<span class="ac-cat-amt">' + fmt(r.total) + '</span>' +
      '</div>';
    }).join('');
    el.querySelectorAll('.ac-cat-row').forEach(function (row) {
      row.addEventListener('click', function () { frappe.set_route('Form', 'Account', row.dataset.account); });
    });
  };

  var AGING_BUCKETS = [
    { key: 'not_due', label: 'Not Due', color: 'var(--c-emerald)' },
    { key: '0-30', label: '0-30d', color: '#22c55e' },
    { key: '31-60', label: '31-60d', color: '#f59e0b' },
    { key: '61-90', label: '61-90d', color: '#f97316' },
    { key: '90+', label: '90+d', color: '#ef4444' }
  ];

  var populateAging = function (containerId, buckets) {
    var el = q('#' + containerId);
    if (!el) return;
    if (!buckets) { el.innerHTML = '<div class="ac-loader">No data</div>'; return; }
    var max = Math.max.apply(null, AGING_BUCKETS.map(function (b) { return parseFloat(buckets[b.key]) || 0; }));
    el.innerHTML = AGING_BUCKETS.map(function (b) {
      var val = parseFloat(buckets[b.key]) || 0;
      var pct = max > 0 ? Math.round(val / max * 100) : 0;
      return '<div class="ac-aging-row">' +
        '<span class="ac-aging-label">' + b.label + '</span>' +
        '<div class="ac-aging-track"><div class="ac-aging-fill" style="width:' + pct + '%;background:' + b.color + '"></div></div>' +
        '<span class="ac-aging-val">' + fmt(val) + '</span>' +
      '</div>';
    }).join('');
  };

  var populateParties = function (containerId, rows, doctype, partyField) {
    var el = q('#' + containerId);
    if (!el) return;
    if (!rows || !rows.length) { el.innerHTML = '<div class="ac-loader">No data for this period</div>'; return; }
    el.innerHTML = rows.map(function (r, i) {
      return '<div class="ac-party-row" data-name="' + r[partyField] + '">' +
        '<span class="ac-party-rank">#' + (i + 1) + '</span>' +
        '<div class="ac-party-info">' +
          '<div class="ac-party-name">' + (r[partyField + '_name'] || r[partyField]) + '</div>' +
          '<div class="ac-party-sub">' + (r.count || 0) + ' invoices</div>' +
        '</div>' +
        '<span class="ac-party-total">' + fmt(r.total) + '</span>' +
      '</div>';
    }).join('');
    el.querySelectorAll('.ac-party-row').forEach(function (row) {
      row.addEventListener('click', function () { frappe.set_route('Form', doctype, row.dataset.name); });
    });
  };

  var populateBankAccounts = function (rows) {
    var el = q('#ac-bank-accounts');
    if (!el) return;
    if (!rows || !rows.length) { el.innerHTML = '<div class="ac-loader">No bank/cash accounts found</div>'; return; }
    el.innerHTML = rows.map(function (a) {
      var isCash = (a.account_type === 'Cash');
      var iconCls = isCash ? 'cash' : 'bank';
      return '<div class="ac-bank-row" data-account="' + a.account + '" style="cursor:pointer">' +
        '<div class="ac-bank-icon ' + iconCls + '">' + (isCash ? '💵' : '🏦') + '</div>' +
        '<div style="flex:1"><div class="ac-bank-name">' + (a.account_name || a.account) + '</div><div class="ac-bank-type">' + a.account_type + '</div></div>' +
        '<span class="ac-bank-balance">' + fmt(a.balance) + '</span>' +
      '</div>';
    }).join('');
    el.querySelectorAll('.ac-bank-row').forEach(function (row) {
      row.addEventListener('click', function () { frappe.set_route('Form', 'Account', row.dataset.account); });
    });
  };

  var populateOverdue = function (containerId, rows, doctype) {
    var el = q('#' + containerId);
    if (!el) return;
    if (!rows || !rows.length) { el.innerHTML = '<div class="ac-loader">Nothing overdue 🎉</div>'; return; }
    el.innerHTML = rows.map(function (inv) {
      return '<div class="ac-overdue-row" data-name="' + inv.name + '">' +
        '<div class="ac-overdue-info">' +
          '<div class="ac-overdue-name">' + inv.name + '</div>' +
          '<div class="ac-overdue-sub">' + (inv.party_name || inv.party || '—') + ' · Due ' + (inv.due_date || '—') + '</div>' +
        '</div>' +
        '<span class="ac-overdue-amt">' + fmt(inv.outstanding_amount) + '</span>' +
      '</div>';
    }).join('');
    el.querySelectorAll('.ac-overdue-row').forEach(function (row) {
      row.addEventListener('click', function () { frappe.set_route('Form', doctype, row.dataset.name); });
    });
  };

  var refresh = function () {
    var btn = q('#acRefreshBtn');
    if (btn) btn.classList.add('spinning');
    setLoading(true);

    frappe.call({
      method: 'jagadamba.jagadamba.accounting_dashboard.get_accounting_dashboard_data',
      args: { period: currentPeriod },
      callback: function (r) {
        if (btn) btn.classList.remove('spinning');
        setLoading(false);
        if (r.exc || !r.message) {
          frappe.msgprint({ title: 'Dashboard Error', message: 'Failed to load. Check console.', indicator: 'red' });
          console.error('Accounting Dashboard Error:', r.exc);
          return;
        }
        dashData = r.message;
        populateKPIs(dashData);
        populateTrend(dashData.monthly_trend);
        populateCategoryList('ac-expense-cat', dashData.expense_by_category, 'var(--c-rose)');
        populateCategoryList('ac-income-cat', dashData.income_by_category, 'var(--c-emerald)');
        populateAging('ac-receivable-aging', dashData.receivable_aging);
        populateAging('ac-payable-aging', dashData.payable_aging);
        populateParties('ac-top-customers', dashData.top_customers, 'Customer', 'customer');
        populateParties('ac-top-suppliers', dashData.top_suppliers, 'Supplier', 'supplier');
        populateBankAccounts(dashData.bank_cash_accounts);
        populateOverdue('ac-overdue-receivables', dashData.overdue_receivables, 'Sales Invoice');
        populateOverdue('ac-overdue-payables', dashData.overdue_payables, 'Purchase Invoice');
      },
      error: function (r) {
        if (btn) btn.classList.remove('spinning');
        setLoading(false);
        console.error('Accounting Dashboard Error:', r);
      }
    });
  };

  var attachListeners = function () {
    var refreshBtn = q('#acRefreshBtn');
    if (refreshBtn) refreshBtn.addEventListener('click', refresh);

    var themeBtn = q('#acThemeBtn');
    if (themeBtn) themeBtn.addEventListener('click', toggleTheme);

    var periodSel = q('#acPeriodSelect');
    if (periodSel) periodSel.addEventListener('change', function () { currentPeriod = this.value; refresh(); });

    var kpiRevenue = q('#ac-kpi-revenue');
    if (kpiRevenue) kpiRevenue.addEventListener('click', function () { frappe.set_route('List', 'Sales Invoice'); });
    var kpiExpense = q('#ac-kpi-expense');
    if (kpiExpense) kpiExpense.addEventListener('click', function () { frappe.set_route('List', 'Purchase Invoice'); });
    var kpiReceivable = q('#ac-kpi-receivable');
    if (kpiReceivable) kpiReceivable.addEventListener('click', function () {
      frappe.set_route('List', 'Sales Invoice', { outstanding_amount: ['>', 0] });
    });
    var kpiPayable = q('#ac-kpi-payable');
    if (kpiPayable) kpiPayable.addEventListener('click', function () {
      frappe.set_route('List', 'Purchase Invoice', { outstanding_amount: ['>', 0] });
    });

    var linkCust = q('#ac-link-customers');
    if (linkCust) linkCust.addEventListener('click', function () { frappe.set_route('List', 'Customer'); });
    var linkSupp = q('#ac-link-suppliers');
    if (linkSupp) linkSupp.addEventListener('click', function () { frappe.set_route('List', 'Supplier'); });
    var linkOR = q('#ac-link-overdue-rec');
    if (linkOR) linkOR.addEventListener('click', function () { frappe.set_route('List', 'Sales Invoice', { outstanding_amount: ['>', 0] }); });
    var linkOP = q('#ac-link-overdue-pay');
    if (linkOP) linkOP.addEventListener('click', function () { frappe.set_route('List', 'Purchase Invoice', { outstanding_amount: ['>', 0] }); });
  };

  loadTheme();
  setDate();
  attachListeners();
  refresh();

}, 1000);

style:
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500&display=swap');

.ac-dash {
  --bg: #f4f6fb;
  --surface: #ffffff;
  --surface2: #f7f9fd;
  --border: #e5e9f2;
  --border-md: #d0d7e8;
  --text-1: #111827;
  --text-2: #4b5675;
  --text-3: #9ca3b8;
  --c-emerald: #059669; --c-emerald-bg: #ecfdf5;
  --c-blue: #2563eb;    --c-blue-bg: #eff6ff;
  --c-amber: #d97706;   --c-amber-bg: #fffbeb;
  --c-rose: #e11d48;    --c-rose-bg: #fff1f2;
  --c-teal: #0d9488;    --c-teal-bg: #f0fdfa;
  --c-violet: #7c3aed;  --c-violet-bg: #f5f3ff;
  --shadow: 0 1px 4px rgba(17,24,39,0.06), 0 0 0 1px var(--border);
  --shadow-hover: 0 6px 20px rgba(17,24,39,0.1), 0 0 0 1px var(--border-md);
  --radius: 14px; --radius-sm: 9px;
  font-family: 'Plus Jakarta Sans', sans-serif;
  background: var(--bg);
  color: var(--text-1);
  padding: 24px 22px;
  min-height: 100vh;
  transition: background 0.3s, color 0.3s;
}

.ac-dash.dark {
  --bg: #0f1117; --surface: #161b26; --surface2: #1d2333;
  --border: #242c3f; --border-md: #2e3850;
  --text-1: #e8ecf5; --text-2: #7c8db0; --text-3: #4a5568;
  --c-emerald: #10b981; --c-emerald-bg: rgba(16,185,129,0.12);
  --c-blue: #3b82f6;    --c-blue-bg: rgba(59,130,246,0.12);
  --c-amber: #f59e0b;   --c-amber-bg: rgba(245,158,11,0.12);
  --c-rose: #f43f5e;    --c-rose-bg: rgba(244,63,94,0.12);
  --c-teal: #14b8a6;    --c-teal-bg: rgba(20,184,166,0.12);
  --c-violet: #8b5cf6;  --c-violet-bg: rgba(139,92,246,0.12);
  --shadow: 0 1px 4px rgba(0,0,0,0.35), 0 0 0 1px var(--border);
  --shadow-hover: 0 6px 24px rgba(0,0,0,0.4), 0 0 0 1px var(--border-md);
}

.ac-header { display:flex; align-items:center; justify-content:space-between; margin-bottom:22px; flex-wrap:wrap; gap:12px; }
.ac-eyebrow { font-family:'JetBrains Mono',monospace; font-size:10px; letter-spacing:0.2em; color:var(--c-emerald); text-transform:uppercase; display:block; margin-bottom:4px; }
.ac-title { font-size:24px; font-weight:800; color:var(--text-1); margin:0; letter-spacing:-0.025em; line-height:1; }
.ac-header-right { display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
.ac-date { font-family:'JetBrains Mono',monospace; font-size:11px; color:var(--text-3); }

.ac-period-select { font-family:'Plus Jakarta Sans',sans-serif; font-size:12px; font-weight:500; background:var(--surface); border:1px solid var(--border-md); color:var(--text-2); padding:6px 10px; border-radius:7px; cursor:pointer; outline:none; }

.ac-btn { display:flex; align-items:center; gap:6px; background:var(--surface); border:1px solid var(--border-md); color:var(--text-2); font-family:'Plus Jakarta Sans',sans-serif; font-size:12px; font-weight:600; padding:6px 12px; border-radius:7px; cursor:pointer; transition:all 0.18s; position:relative; overflow:hidden; }
.ac-btn:hover { border-color:var(--c-emerald); color:var(--c-emerald); }
.ac-btn.spinning svg { animation:ac-spin 0.6s linear infinite; }
@keyframes ac-spin { to { transform:rotate(360deg); } }

.ac-icon-sun,.ac-icon-moon { position:absolute; left:50%; top:50%; transition:transform 0.4s cubic-bezier(0.34,1.56,0.64,1),opacity 0.2s; }
.ac-icon-sun { opacity:1; transform:translate(-50%,-50%) rotate(0) scale(1); }
.ac-icon-moon { opacity:0; transform:translate(-50%,-50%) rotate(90deg) scale(0.5); }
.ac-dash.dark .ac-icon-sun { opacity:0; transform:translate(-50%,-50%) rotate(-90deg) scale(0.5); }
.ac-dash.dark .ac-icon-moon { opacity:1; transform:translate(-50%,-50%) rotate(0) scale(1); }
#acThemeBtn { width:34px; height:32px; padding:0; }

.ac-section-label { font-size:10px; font-weight:700; letter-spacing:0.12em; text-transform:uppercase; color:var(--text-3); margin:20px 0 10px; font-family:'JetBrains Mono',monospace; }

/* KPI row */
.ac-kpi-row { display:grid; grid-template-columns:repeat(6,minmax(0,1fr)); gap:12px; }
@media (max-width:1300px) { .ac-kpi-row { grid-template-columns:repeat(3,minmax(0,1fr)); } }
@media (max-width:700px)  { .ac-kpi-row { grid-template-columns:repeat(2,minmax(0,1fr)); } }

.ac-kpi { background:var(--surface); border-radius:var(--radius); box-shadow:var(--shadow); padding:16px; position:relative; overflow:hidden; transition:box-shadow 0.2s,transform 0.2s; }
.ac-kpi:hover { box-shadow:var(--shadow-hover); transform:translateY(-2px); }
.ac-kpi-accent { position:absolute; left:0; top:0; bottom:0; width:3px; }
.ac-kpi.blue .ac-kpi-accent    { background:var(--c-blue); }
.ac-kpi.amber .ac-kpi-accent   { background:var(--c-amber); }
.ac-kpi.violet .ac-kpi-accent  { background:var(--c-violet); }
.ac-kpi.teal .ac-kpi-accent    { background:var(--c-teal); }
.ac-kpi.emerald .ac-kpi-accent { background:var(--c-emerald); }
.ac-kpi.rose .ac-kpi-accent    { background:var(--c-rose); }
.ac-kpi-body { display:flex; flex-direction:column; gap:2px; }
.ac-kpi-label { font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:0.07em; color:var(--text-3); }
.ac-kpi-val { font-size:22px; font-weight:800; color:var(--text-1); letter-spacing:-0.02em; }
.ac-kpi-sub { font-family:'JetBrains Mono',monospace; font-size:10px; color:var(--text-3); margin-top:2px; }

/* Panels */
.ac-panel { background:var(--surface); border-radius:var(--radius); box-shadow:var(--shadow); overflow:hidden; }
.ac-panel-header { display:flex; justify-content:space-between; align-items:center; padding:14px 16px; border-bottom:1px solid var(--border); background:var(--surface2); }
.ac-panel-title { font-size:12px; font-weight:700; color:var(--text-1); }
.ac-panel-link { font-size:11px; color:var(--c-blue); cursor:pointer; font-weight:600; text-decoration:none; }
.ac-panel-link:hover { opacity:0.65; }
.ac-panel-body { padding:8px 0; min-height:100px; }
.ac-loader { text-align:center; padding:34px; color:var(--text-3); font-family:'JetBrains Mono',monospace; font-size:11px; }

.ac-two-col { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:12px; margin-top:20px; }
@media (max-width:900px) { .ac-two-col { grid-template-columns:1fr; } }

/* Trend chart (CSS bars) */
.ac-trend-body { display:flex; align-items:flex-end; justify-content:space-around; height:220px; padding:16px 16px 8px; gap:8px; }
.ac-trend-col { display:flex; flex-direction:column; align-items:center; gap:6px; flex:1; height:100%; justify-content:flex-end; }
.ac-trend-bars { display:flex; align-items:flex-end; gap:4px; height:170px; width:100%; justify-content:center; }
.ac-trend-bar { width:16px; border-radius:4px 4px 0 0; transition:height 0.5s cubic-bezier(0.4,0,0.2,1); min-height:2px; }
.ac-trend-bar.income { background:var(--c-emerald); }
.ac-trend-bar.expense { background:var(--c-rose); }
.ac-trend-month { font-family:'JetBrains Mono',monospace; font-size:10px; color:var(--text-3); }
.ac-legend { display:flex; gap:16px; justify-content:center; padding:6px 0 14px; }
.ac-legend-item { display:flex; align-items:center; gap:6px; font-family:'JetBrains Mono',monospace; font-size:10px; color:var(--text-2); }
.ac-dot { width:8px; height:8px; border-radius:50%; display:inline-block; }
.ac-dot.emerald { background:var(--c-emerald); }
.ac-dot.rose { background:var(--c-rose); }

/* Category bars (expense/income) */
.ac-cat-row { display:flex; align-items:center; gap:10px; padding:9px 16px; border-bottom:1px solid var(--border); cursor:pointer; transition:background 0.15s; }
.ac-cat-row:last-child { border-bottom:none; }
.ac-cat-row:hover { background:var(--surface2); }
.ac-cat-name { font-size:12px; font-weight:600; color:var(--text-1); min-width:130px; flex-shrink:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.ac-cat-bar-wrap { flex:1; height:7px; background:var(--border); border-radius:4px; overflow:hidden; }
.ac-cat-bar { height:100%; border-radius:4px; transition:width 0.6s cubic-bezier(0.4,0,0.2,1); }
.ac-cat-amt { font-family:'JetBrains Mono',monospace; font-size:11px; color:var(--text-2); min-width:64px; text-align:right; flex-shrink:0; }

/* Aging */
.ac-aging-body { padding:16px; display:flex; flex-direction:column; gap:12px; }
.ac-aging-row { display:flex; align-items:center; gap:10px; }
.ac-aging-label { font-family:'JetBrains Mono',monospace; font-size:10px; font-weight:700; color:var(--text-2); min-width:64px; }
.ac-aging-track { flex:1; height:8px; background:var(--border); border-radius:4px; overflow:hidden; }
.ac-aging-fill { height:100%; border-radius:4px; transition:width 0.6s cubic-bezier(0.4,0,0.2,1); }
.ac-aging-val { font-family:'JetBrains Mono',monospace; font-size:11px; color:var(--text-1); min-width:70px; text-align:right; }

/* Customer / supplier rows */
.ac-party-row { display:flex; align-items:center; gap:10px; padding:9px 16px; border-bottom:1px solid var(--border); cursor:pointer; transition:background 0.15s; }
.ac-party-row:last-child { border-bottom:none; }
.ac-party-row:hover { background:var(--surface2); }
.ac-party-rank { font-family:'JetBrains Mono',monospace; font-size:10px; font-weight:700; color:var(--text-3); width:18px; flex-shrink:0; }
.ac-party-info { flex:1; min-width:0; }
.ac-party-name { font-size:12px; font-weight:600; color:var(--text-1); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.ac-party-sub { font-family:'JetBrains Mono',monospace; font-size:10px; color:var(--text-3); }
.ac-party-total { font-family:'JetBrains Mono',monospace; font-size:12px; font-weight:600; color:var(--c-emerald); flex-shrink:0; }

/* Bank accounts */
.ac-bank-row { display:flex; align-items:center; gap:12px; padding:10px 16px; border-bottom:1px solid var(--border); }
.ac-bank-row:last-child { border-bottom:none; }
.ac-bank-icon { width:32px; height:32px; border-radius:8px; display:flex; align-items:center; justify-content:center; flex-shrink:0; }
.ac-bank-icon.bank { background:var(--c-blue-bg); color:var(--c-blue); }
.ac-bank-icon.cash { background:var(--c-emerald-bg); color:var(--c-emerald); }
.ac-bank-name { font-size:12px; font-weight:600; color:var(--text-1); flex:1; }
.ac-bank-type { font-family:'JetBrains Mono',monospace; font-size:9px; color:var(--text-3); }
.ac-bank-balance { font-family:'JetBrains Mono',monospace; font-size:13px; font-weight:700; color:var(--text-1); }

/* Overdue */
.ac-overdue-row { display:flex; align-items:center; gap:10px; padding:9px 16px; border-bottom:1px solid var(--border); cursor:pointer; transition:background 0.15s; }
.ac-overdue-row:last-child { border-bottom:none; }
.ac-overdue-row:hover { background:var(--surface2); }
.ac-overdue-info { flex:1; min-width:0; }
.ac-overdue-name { font-size:12px; font-weight:600; color:var(--text-1); }
.ac-overdue-sub { font-family:'JetBrains Mono',monospace; font-size:10px; color:var(--text-3); }
.ac-overdue-amt { font-family:'JetBrains Mono',monospace; font-size:12px; font-weight:700; color:var(--c-rose); flex-shrink:0; }

.ac-pulse { animation:ac-pulse-anim 1.4s ease-in-out infinite; }
@keyframes ac-pulse-anim { 0%,100% { opacity:1; } 50% { opacity:0.3; } }

script:
setTimeout(function () {

  var root = root_element;
  var currentPeriod = 'this_month';
  var dashData = {};
  var THEME_KEY = 'jagdamba_sales_dash_theme';

  var q  = function (s) { return root.querySelector(s); };
  var qa = function (s) { return root.querySelectorAll(s); };

  var getDashEl = function () { return q('#slSalesDashboard') || root; };

  var applyTheme = function (t) {
    if (t === 'dark') getDashEl().classList.add('dark');
    else getDashEl().classList.remove('dark');
  };
  var toggleTheme = function () {
    var isDark = getDashEl().classList.contains('dark');
    var next = isDark ? 'light' : 'dark';
    applyTheme(next);
    try { localStorage.setItem(THEME_KEY, next); } catch (e) {}
  };
  var loadTheme = function () {
    try {
      var saved = localStorage.getItem(THEME_KEY);
      if (saved) { applyTheme(saved); return; }
    } catch (e) {}
    applyTheme('light');
  };

  var setText = function (id, v) {
    var el = q('#' + id);
    if (el) el.textContent = (v !== null && v !== undefined) ? v : '—';
  };

  var fmt = function (val) {
    var num = parseFloat(val) || 0;
    var neg = num < 0;
    num = Math.abs(num);
    var out;
    if (num >= 1000000) out = (num / 1000000).toFixed(2) + 'M';
    else if (num >= 1000) out = (num / 1000).toFixed(1) + 'K';
    else out = num.toLocaleString('en-AE', { minimumFractionDigits: 0, maximumFractionDigits: 0 });
    return (neg ? '-' : '') + out;
  };

  var setDate = function () {
    var el = q('#slDate');
    if (el) el.textContent = new Date().toLocaleDateString('en-US', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric' });
  };

  var setLoading = function (on) {
    var ids = ['sl-leads', 'sl-quotations', 'sl-so', 'sl-conversion', 'sl-avgdeal', 'sl-open'];
    ids.forEach(function (id) {
      var el = q('#' + id);
      if (!el) return;
      if (on) { el.textContent = '…'; el.classList.add('sl-pulse'); }
      else el.classList.remove('sl-pulse');
    });
  };

  var statusClass = function (status) {
    var map = {
      'Draft': 's-draft', 'Open': 's-open', 'Replied': 's-replied',
      'Ordered': 's-ordered', 'Lost': 's-lost', 'Cancelled': 's-cancelled',
      'Expired': 's-expired', 'Completed': 's-completed', 'To Deliver and Bill': 's-open',
      'To Bill': 's-open', 'To Deliver': 's-open'
    };
    return map[status] || 's-open';
  };

  var populateKPIs = function (d) {
    var k = d.kpis || {};
    setText('sl-leads', k.total_leads);
    setText('sl-quotations', k.quotation_count);
    setText('sl-quotation-value', 'AED ' + fmt(k.quotation_value));
    setText('sl-so', k.sales_order_count);
    setText('sl-so-value', 'AED ' + fmt(k.sales_order_value));
    setText('sl-conversion', (k.conversion_rate || 0) + '%');
    setText('sl-avgdeal', 'AED ' + fmt(k.avg_deal_size));
    setText('sl-open', k.open_quotations);
    setText('slPeriodLabel', d.period_label || '');
  };

  var FUNNEL_COLORS = ['var(--c-blue)', 'var(--c-amber)', 'var(--c-emerald)', 'var(--c-teal)'];

  var populateFunnel = function (rows) {
    var el = q('#sl-funnel');
    if (!el) return;
    if (!rows || !rows.length) { el.innerHTML = '<div class="sl-loader">No data</div>'; return; }
    var max = Math.max.apply(null, rows.map(function (r) { return r.count || 0; }));
    var base = rows[0].count || 0;
    el.innerHTML = rows.map(function (r, i) {
      var pct = max > 0 ? Math.round((r.count || 0) / max * 100) : 0;
      var ofBase = base > 0 ? Math.round((r.count || 0) / base * 100) : 0;
      return '<div class="sl-funnel-row">' +
        '<span class="sl-funnel-label">' + r.stage + '</span>' +
        '<div class="sl-funnel-track"><div class="sl-funnel-fill" style="width:' + Math.max(pct, 6) + '%;background:' + FUNNEL_COLORS[i % FUNNEL_COLORS.length] + '"><span class="sl-funnel-count">' + r.count + '</span></div></div>' +
        '<span class="sl-funnel-pct">' + ofBase + '%</span>' +
      '</div>';
    }).join('');
  };

  var populateTrend = function (rows) {
    var el = q('#sl-trend-chart');
    if (!el) return;
    if (!rows || !rows.length) { el.innerHTML = '<div class="sl-loader">No data</div>'; return; }
    var max = 0;
    rows.forEach(function (r) {
      max = Math.max(max, parseFloat(r.quotation) || 0, parseFloat(r.sales_order) || 0);
    });
    el.innerHTML = rows.map(function (r) {
      var qH = max > 0 ? Math.round((parseFloat(r.quotation) || 0) / max * 170) : 2;
      var sH = max > 0 ? Math.round((parseFloat(r.sales_order) || 0) / max * 170) : 2;
      return '<div class="sl-trend-col" title="' + r.month + ': Quotation ' + fmt(r.quotation) + ' · SO ' + fmt(r.sales_order) + '">' +
        '<div class="sl-trend-bars">' +
          '<div class="sl-trend-bar quotation" style="height:' + qH + 'px"></div>' +
          '<div class="sl-trend-bar sales_order" style="height:' + sH + 'px"></div>' +
        '</div>' +
        '<span class="sl-trend-month">' + r.month + '</span>' +
      '</div>';
    }).join('');
  };

  var populateVehicleTypeSplit = function (rows) {
    var el = q('#sl-vt-split');
    if (!el) return;
    if (!rows || !rows.length) { el.innerHTML = '<div class="sl-loader">No Sales Orders in this period</div>'; return; }
    var max = Math.max.apply(null, rows.map(function (r) { return parseFloat(r.total) || 0; }));
    el.innerHTML = rows.map(function (r) {
      var pct = max > 0 ? Math.round((parseFloat(r.total) || 0) / max * 100) : 0;
      return '<div class="sl-bar-row" data-vt="' + (r.vehicle_type || '') + '">' +
        '<span class="sl-bar-name">' + (r.vehicle_type || 'Unassigned') + '</span>' +
        '<div class="sl-bar-wrap"><div class="sl-bar-fill" style="width:' + pct + '%;background:var(--c-blue)"></div></div>' +
        '<span class="sl-bar-val">' + fmt(r.total) + '</span>' +
      '</div>';
    }).join('');
    el.querySelectorAll('.sl-bar-row').forEach(function (row) {
      row.addEventListener('click', function () { frappe.set_route('List', 'Sales Order'); });
    });
  };

  var populateLeadSource = function (rows) {
    var el = q('#sl-lead-source');
    if (!el) return;
    if (!rows || !rows.length) { el.innerHTML = '<div class="sl-loader">No leads in this period</div>'; return; }
    var max = Math.max.apply(null, rows.map(function (r) { return r.count || 0; }));
    el.innerHTML = rows.map(function (r) {
      var pct = max > 0 ? Math.round((r.count || 0) / max * 100) : 0;
      return '<div class="sl-bar-row" data-src="' + (r.source || '') + '">' +
        '<span class="sl-bar-name">' + (r.source || 'Unknown') + '</span>' +
        '<div class="sl-bar-wrap"><div class="sl-bar-fill" style="width:' + pct + '%;background:var(--c-violet)"></div></div>' +
        '<span class="sl-bar-val">' + r.count + '</span>' +
      '</div>';
    }).join('');
    el.querySelectorAll('.sl-bar-row').forEach(function (row) {
      row.addEventListener('click', function () { frappe.set_route('List', 'Lead', { source: row.dataset.src }); });
    });
  };

  var populateQuoteStatus = function (rows) {
    var el = q('#sl-quote-status');
    if (!el) return;
    if (!rows || !rows.length) { el.innerHTML = '<div class="sl-loader">No quotations in this period</div>'; return; }
    var max = Math.max.apply(null, rows.map(function (r) { return r.count || 0; }));
    el.innerHTML = rows.map(function (r) {
      var pct = max > 0 ? Math.round((r.count || 0) / max * 100) : 0;
      return '<div class="sl-bar-row" data-status="' + r.status + '">' +
        '<span class="sl-bar-name">' + r.status + '</span>' +
        '<div class="sl-bar-wrap"><div class="sl-bar-fill" style="width:' + pct + '%;background:var(--c-amber)"></div></div>' +
        '<span class="sl-bar-val">' + r.count + '</span>' +
      '</div>';
    }).join('');
    el.querySelectorAll('.sl-bar-row').forEach(function (row) {
      row.addEventListener('click', function () { frappe.set_route('List', 'Quotation', { status: row.dataset.status }); });
    });
  };

  var populateTopCustomers = function (rows) {
    var el = q('#sl-top-customers');
    if (!el) return;
    if (!rows || !rows.length) { el.innerHTML = '<div class="sl-loader">No Sales Orders in this period</div>'; return; }
    el.innerHTML = rows.map(function (r, i) {
      return '<div class="sl-party-row" data-name="' + r.customer + '">' +
        '<span class="sl-party-rank">#' + (i + 1) + '</span>' +
        '<div class="sl-party-info">' +
          '<div class="sl-party-name">' + (r.customer_name || r.customer) + '</div>' +
          '<div class="sl-party-sub">' + (r.count || 0) + ' orders</div>' +
        '</div>' +
        '<span class="sl-party-total">' + fmt(r.total) + '</span>' +
      '</div>';
    }).join('');
    el.querySelectorAll('.sl-party-row').forEach(function (row) {
      row.addEventListener('click', function () { frappe.set_route('Form', 'Customer', row.dataset.name); });
    });
  };

  var populateRecentQuotations = function (rows) {
    var el = q('#sl-recent-quotations');
    if (!el) return;
    if (!rows || !rows.length) { el.innerHTML = '<div class="sl-loader">No quotations found</div>'; return; }
    el.innerHTML = rows.map(function (r) {
      return '<div class="sl-doc-row" data-name="' + r.name + '">' +
        '<div class="sl-doc-info">' +
          '<div class="sl-doc-name">' + (r.customer_name || r.name) + '</div>' +
          '<div class="sl-doc-sub">' + r.name + (r.custom_vehicle_type ? ' · ' + r.custom_vehicle_type : '') + '</div>' +
          '<span class="sl-status-badge ' + statusClass(r.status) + '">' + r.status + '</span>' +
        '</div>' +
        '<span class="sl-doc-amt">' + fmt(r.grand_total) + '</span>' +
      '</div>';
    }).join('');
    el.querySelectorAll('.sl-doc-row').forEach(function (row) {
      row.addEventListener('click', function () { frappe.set_route('Form', 'Quotation', row.dataset.name); });
    });
  };

  var populateRecentSO = function (rows) {
    var el = q('#sl-recent-so');
    if (!el) return;
    if (!rows || !rows.length) { el.innerHTML = '<div class="sl-loader">No Sales Orders found</div>'; return; }
    el.innerHTML = rows.map(function (r) {
      return '<div class="sl-doc-row" data-name="' + r.name + '">' +
        '<div class="sl-doc-info">' +
          '<div class="sl-doc-name">' + (r.customer_name || r.name) + '</div>' +
          '<div class="sl-doc-sub">' + r.name + (r.project ? ' · ' + r.project : '') + '</div>' +
          '<span class="sl-status-badge ' + statusClass(r.status) + '">' + r.status + '</span>' +
        '</div>' +
        '<span class="sl-doc-amt">' + fmt(r.grand_total) + '</span>' +
      '</div>';
    }).join('');
    el.querySelectorAll('.sl-doc-row').forEach(function (row) {
      row.addEventListener('click', function () { frappe.set_route('Form', 'Sales Order', row.dataset.name); });
    });
  };

  var populateLostQuotations = function (rows) {
    var el = q('#sl-lost-quotations');
    if (!el) return;
    if (!rows || !rows.length) { el.innerHTML = '<div class="sl-loader">No lost quotations 🎉</div>'; return; }
    el.innerHTML = rows.map(function (r) {
      return '<div class="sl-lost-row" data-name="' + r.name + '">' +
        '<div class="sl-lost-info">' +
          '<div class="sl-lost-name">' + (r.customer_name || r.name) + ' · ' + r.name + '</div>' +
          '<div class="sl-lost-reason">' + (r.order_lost_reason || 'No reason recorded') + '</div>' +
        '</div>' +
        '<span class="sl-lost-amt">' + fmt(r.grand_total) + '</span>' +
      '</div>';
    }).join('');
    el.querySelectorAll('.sl-lost-row').forEach(function (row) {
      row.addEventListener('click', function () { frappe.set_route('Form', 'Quotation', row.dataset.name); });
    });
  };

  var refresh = function () {
    var btn = q('#slRefreshBtn');
    if (btn) btn.classList.add('spinning');
    setLoading(true);

    frappe.call({
      method: 'jagadamba.jagadamba.sales_dashboard.get_sales_dashboard_data',
      args: { period: currentPeriod },
      callback: function (r) {
        if (btn) btn.classList.remove('spinning');
        setLoading(false);
        if (r.exc || !r.message) {
          frappe.msgprint({ title: 'Dashboard Error', message: 'Failed to load. Check console.', indicator: 'red' });
          console.error('Sales Dashboard Error:', r.exc);
          return;
        }
        dashData = r.message;
        populateKPIs(dashData);
        populateFunnel(dashData.funnel);
        populateTrend(dashData.monthly_trend);
        populateVehicleTypeSplit(dashData.vehicle_type_split);
        populateLeadSource(dashData.lead_source_split);
        populateQuoteStatus(dashData.quotation_status);
        populateTopCustomers(dashData.top_customers);
        populateRecentQuotations(dashData.recent_quotations);
        populateRecentSO(dashData.recent_sales_orders);
        populateLostQuotations(dashData.lost_quotations);
      },
      error: function (r) {
        if (btn) btn.classList.remove('spinning');
        setLoading(false);
        console.error('Sales Dashboard Error:', r);
      }
    });
  };

  var attachListeners = function () {
    var refreshBtn = q('#slRefreshBtn');
    if (refreshBtn) refreshBtn.addEventListener('click', refresh);

    var themeBtn = q('#slThemeBtn');
    if (themeBtn) themeBtn.addEventListener('click', toggleTheme);

    var periodSel = q('#slPeriodSelect');
    if (periodSel) periodSel.addEventListener('change', function () { currentPeriod = this.value; refresh(); });

    var kpiLeads = q('#sl-kpi-leads');
    if (kpiLeads) kpiLeads.addEventListener('click', function () { frappe.set_route('List', 'Lead'); });
    var kpiQuotations = q('#sl-kpi-quotations');
    if (kpiQuotations) kpiQuotations.addEventListener('click', function () { frappe.set_route('List', 'Quotation'); });
    var kpiSo = q('#sl-kpi-so');
    if (kpiSo) kpiSo.addEventListener('click', function () { frappe.set_route('List', 'Sales Order'); });
    var kpiOpen = q('#sl-kpi-open');
    if (kpiOpen) kpiOpen.addEventListener('click', function () {
      frappe.set_route('List', 'Quotation', { status: ['in', ['Draft', 'Open', 'Replied']] });
    });

    var linkCust = q('#sl-link-customers');
    if (linkCust) linkCust.addEventListener('click', function () { frappe.set_route('List', 'Customer'); });
    var linkQuot = q('#sl-link-quotations');
    if (linkQuot) linkQuot.addEventListener('click', function () { frappe.set_route('List', 'Quotation'); });
    var linkSo = q('#sl-link-so');
    if (linkSo) linkSo.addEventListener('click', function () { frappe.set_route('List', 'Sales Order'); });
  };

  loadTheme();
  setDate();
  attachListeners();
  refresh();

}, 1000);

style:
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500&display=swap');

.sl-dash {
  --bg: #f4f6fb;
  --surface: #ffffff;
  --surface2: #f7f9fd;
  --border: #e5e9f2;
  --border-md: #d0d7e8;
  --text-1: #111827;
  --text-2: #4b5675;
  --text-3: #9ca3b8;
  --c-emerald: #059669; --c-emerald-bg: #ecfdf5;
  --c-blue: #2563eb;    --c-blue-bg: #eff6ff;
  --c-amber: #d97706;   --c-amber-bg: #fffbeb;
  --c-rose: #e11d48;    --c-rose-bg: #fff1f2;
  --c-teal: #0d9488;    --c-teal-bg: #f0fdfa;
  --c-violet: #7c3aed;  --c-violet-bg: #f5f3ff;
  --shadow: 0 1px 4px rgba(17,24,39,0.06), 0 0 0 1px var(--border);
  --shadow-hover: 0 6px 20px rgba(17,24,39,0.1), 0 0 0 1px var(--border-md);
  --radius: 14px; --radius-sm: 9px;
  font-family: 'Plus Jakarta Sans', sans-serif;
  background: var(--bg);
  color: var(--text-1);
  padding: 24px 22px;
  min-height: 100vh;
  transition: background 0.3s, color 0.3s;
}

.sl-dash.dark {
  --bg: #0f1117; --surface: #161b26; --surface2: #1d2333;
  --border: #242c3f; --border-md: #2e3850;
  --text-1: #e8ecf5; --text-2: #7c8db0; --text-3: #4a5568;
  --c-emerald: #10b981; --c-emerald-bg: rgba(16,185,129,0.12);
  --c-blue: #3b82f6;    --c-blue-bg: rgba(59,130,246,0.12);
  --c-amber: #f59e0b;   --c-amber-bg: rgba(245,158,11,0.12);
  --c-rose: #f43f5e;    --c-rose-bg: rgba(244,63,94,0.12);
  --c-teal: #14b8a6;    --c-teal-bg: rgba(20,184,166,0.12);
  --c-violet: #8b5cf6;  --c-violet-bg: rgba(139,92,246,0.12);
  --shadow: 0 1px 4px rgba(0,0,0,0.35), 0 0 0 1px var(--border);
  --shadow-hover: 0 6px 24px rgba(0,0,0,0.4), 0 0 0 1px var(--border-md);
}

.sl-header { display:flex; align-items:center; justify-content:space-between; margin-bottom:22px; flex-wrap:wrap; gap:12px; }
.sl-eyebrow { font-family:'JetBrains Mono',monospace; font-size:10px; letter-spacing:0.2em; color:var(--c-blue); text-transform:uppercase; display:block; margin-bottom:4px; }
.sl-title { font-size:24px; font-weight:800; color:var(--text-1); margin:0; letter-spacing:-0.025em; line-height:1; }
.sl-header-right { display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
.sl-date { font-family:'JetBrains Mono',monospace; font-size:11px; color:var(--text-3); }

.sl-period-select { font-family:'Plus Jakarta Sans',sans-serif; font-size:12px; font-weight:500; background:var(--surface); border:1px solid var(--border-md); color:var(--text-2); padding:6px 10px; border-radius:7px; cursor:pointer; outline:none; }

.sl-btn { display:flex; align-items:center; gap:6px; background:var(--surface); border:1px solid var(--border-md); color:var(--text-2); font-family:'Plus Jakarta Sans',sans-serif; font-size:12px; font-weight:600; padding:6px 12px; border-radius:7px; cursor:pointer; transition:all 0.18s; position:relative; overflow:hidden; }
.sl-btn:hover { border-color:var(--c-blue); color:var(--c-blue); }
.sl-btn.spinning svg { animation:sl-spin 0.6s linear infinite; }
@keyframes sl-spin { to { transform:rotate(360deg); } }

.sl-icon-sun,.sl-icon-moon { position:absolute; left:50%; top:50%; transition:transform 0.4s cubic-bezier(0.34,1.56,0.64,1),opacity 0.2s; }
.sl-icon-sun { opacity:1; transform:translate(-50%,-50%) rotate(0) scale(1); }
.sl-icon-moon { opacity:0; transform:translate(-50%,-50%) rotate(90deg) scale(0.5); }
.sl-dash.dark .sl-icon-sun { opacity:0; transform:translate(-50%,-50%) rotate(-90deg) scale(0.5); }
.sl-dash.dark .sl-icon-moon { opacity:1; transform:translate(-50%,-50%) rotate(0) scale(1); }
#slThemeBtn { width:34px; height:32px; padding:0; }

.sl-section-label { font-size:10px; font-weight:700; letter-spacing:0.12em; text-transform:uppercase; color:var(--text-3); margin:20px 0 10px; font-family:'JetBrains Mono',monospace; }

/* KPI row */
.sl-kpi-row { display:grid; grid-template-columns:repeat(6,minmax(0,1fr)); gap:12px; }
@media (max-width:1300px) { .sl-kpi-row { grid-template-columns:repeat(3,minmax(0,1fr)); } }
@media (max-width:700px)  { .sl-kpi-row { grid-template-columns:repeat(2,minmax(0,1fr)); } }

.sl-kpi { background:var(--surface); border-radius:var(--radius); box-shadow:var(--shadow); padding:16px; position:relative; overflow:hidden; transition:box-shadow 0.2s,transform 0.2s; }
.sl-kpi:hover { box-shadow:var(--shadow-hover); transform:translateY(-2px); }
.sl-kpi-accent { position:absolute; left:0; top:0; bottom:0; width:3px; }
.sl-kpi.blue .sl-kpi-accent    { background:var(--c-blue); }
.sl-kpi.amber .sl-kpi-accent   { background:var(--c-amber); }
.sl-kpi.violet .sl-kpi-accent  { background:var(--c-violet); }
.sl-kpi.teal .sl-kpi-accent    { background:var(--c-teal); }
.sl-kpi.emerald .sl-kpi-accent { background:var(--c-emerald); }
.sl-kpi.rose .sl-kpi-accent    { background:var(--c-rose); }
.sl-kpi-body { display:flex; flex-direction:column; gap:2px; }
.sl-kpi-label { font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:0.07em; color:var(--text-3); }
.sl-kpi-val { font-size:22px; font-weight:800; color:var(--text-1); letter-spacing:-0.02em; }
.sl-kpi-sub { font-family:'JetBrains Mono',monospace; font-size:10px; color:var(--text-3); margin-top:2px; }

/* Panels */
.sl-panel { background:var(--surface); border-radius:var(--radius); box-shadow:var(--shadow); overflow:hidden; }
.sl-panel-header { display:flex; justify-content:space-between; align-items:center; padding:14px 16px; border-bottom:1px solid var(--border); background:var(--surface2); }
.sl-panel-title { font-size:12px; font-weight:700; color:var(--text-1); }
.sl-panel-link { font-size:11px; color:var(--c-blue); cursor:pointer; font-weight:600; text-decoration:none; }
.sl-panel-link:hover { opacity:0.65; }
.sl-panel-body { padding:8px 0; min-height:100px; }
.sl-loader { text-align:center; padding:34px; color:var(--text-3); font-family:'JetBrains Mono',monospace; font-size:11px; }

.sl-two-col { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:12px; margin-top:20px; }
@media (max-width:900px) { .sl-two-col { grid-template-columns:1fr; } }

/* Funnel */
.sl-funnel { display:flex; flex-direction:column; gap:10px; padding:18px 22px; }
.sl-funnel-row { display:flex; align-items:center; gap:14px; }
.sl-funnel-label { font-size:11px; font-weight:700; color:var(--text-2); min-width:100px; flex-shrink:0; }
.sl-funnel-track { flex:1; height:26px; background:var(--surface2); border-radius:6px; overflow:hidden; position:relative; }
.sl-funnel-fill { height:100%; border-radius:6px; display:flex; align-items:center; justify-content:flex-end; padding-right:10px; transition:width 0.6s cubic-bezier(0.4,0,0.2,1); }
.sl-funnel-count { font-family:'JetBrains Mono',monospace; font-size:11px; font-weight:700; color:#fff; }
.sl-funnel-pct { font-family:'JetBrains Mono',monospace; font-size:10px; color:var(--text-3); min-width:44px; text-align:right; }

/* Trend chart (CSS bars) */
.sl-trend-body { display:flex; align-items:flex-end; justify-content:space-around; height:220px; padding:16px 16px 8px; gap:8px; }
.sl-trend-col { display:flex; flex-direction:column; align-items:center; gap:6px; flex:1; height:100%; justify-content:flex-end; }
.sl-trend-bars { display:flex; align-items:flex-end; gap:4px; height:170px; width:100%; justify-content:center; }
.sl-trend-bar { width:16px; border-radius:4px 4px 0 0; transition:height 0.5s cubic-bezier(0.4,0,0.2,1); min-height:2px; }
.sl-trend-bar.quotation { background:var(--c-amber); }
.sl-trend-bar.sales_order { background:var(--c-emerald); }
.sl-trend-month { font-family:'JetBrains Mono',monospace; font-size:10px; color:var(--text-3); }
.sl-legend { display:flex; gap:16px; justify-content:center; padding:6px 0 14px; }
.sl-legend-item { display:flex; align-items:center; gap:6px; font-family:'JetBrains Mono',monospace; font-size:10px; color:var(--text-2); }
.sl-dot { width:8px; height:8px; border-radius:50%; display:inline-block; }
.sl-dot.amber { background:var(--c-amber); }
.sl-dot.emerald { background:var(--c-emerald); }

/* Generic ranked bar rows (vehicle type / lead source / status) */
.sl-bar-row { display:flex; align-items:center; gap:10px; padding:9px 16px; border-bottom:1px solid var(--border); cursor:pointer; transition:background 0.15s; }
.sl-bar-row:last-child { border-bottom:none; }
.sl-bar-row:hover { background:var(--surface2); }
.sl-bar-name { font-size:12px; font-weight:600; color:var(--text-1); min-width:120px; flex-shrink:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.sl-bar-wrap { flex:1; height:7px; background:var(--border); border-radius:4px; overflow:hidden; }
.sl-bar-fill { height:100%; border-radius:4px; transition:width 0.6s cubic-bezier(0.4,0,0.2,1); }
.sl-bar-val { font-family:'JetBrains Mono',monospace; font-size:11px; color:var(--text-2); min-width:56px; text-align:right; flex-shrink:0; }

/* Party rows (top customers) */
.sl-party-row { display:flex; align-items:center; gap:10px; padding:9px 16px; border-bottom:1px solid var(--border); cursor:pointer; transition:background 0.15s; }
.sl-party-row:last-child { border-bottom:none; }
.sl-party-row:hover { background:var(--surface2); }
.sl-party-rank { font-family:'JetBrains Mono',monospace; font-size:10px; font-weight:700; color:var(--text-3); width:18px; flex-shrink:0; }
.sl-party-info { flex:1; min-width:0; }
.sl-party-name { font-size:12px; font-weight:600; color:var(--text-1); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.sl-party-sub { font-family:'JetBrains Mono',monospace; font-size:10px; color:var(--text-3); }
.sl-party-total { font-family:'JetBrains Mono',monospace; font-size:12px; font-weight:600; color:var(--c-emerald); flex-shrink:0; }

/* Doc list rows (quotations / SOs) */
.sl-doc-row { display:flex; align-items:center; gap:10px; padding:9px 16px; border-bottom:1px solid var(--border); cursor:pointer; transition:background 0.15s; }
.sl-doc-row:last-child { border-bottom:none; }
.sl-doc-row:hover { background:var(--surface2); }
.sl-doc-info { flex:1; min-width:0; }
.sl-doc-name { font-size:12px; font-weight:600; color:var(--text-1); }
.sl-doc-sub { font-family:'JetBrains Mono',monospace; font-size:10px; color:var(--text-3); }
.sl-doc-amt { font-family:'JetBrains Mono',monospace; font-size:12px; font-weight:700; color:var(--text-1); flex-shrink:0; text-align:right; }
.sl-status-badge { display:inline-block; font-family:'JetBrains Mono',monospace; font-size:8.5px; font-weight:700; padding:2px 7px; border-radius:4px; text-transform:uppercase; margin-top:2px; }
.sl-status-badge.s-draft, .sl-status-badge.s-open { background:rgba(124,131,153,0.12); color:var(--text-2); }
.sl-status-badge.s-replied { background:var(--c-blue-bg); color:var(--c-blue); }
.sl-status-badge.s-ordered, .sl-status-badge.s-completed { background:var(--c-emerald-bg); color:var(--c-emerald); }
.sl-status-badge.s-lost, .sl-status-badge.s-cancelled { background:var(--c-rose-bg); color:var(--c-rose); }
.sl-status-badge.s-expired { background:var(--c-amber-bg); color:var(--c-amber); }

/* Lost quotations */
.sl-lost-row { display:flex; align-items:center; gap:10px; padding:9px 16px; border-bottom:1px solid var(--border); cursor:pointer; transition:background 0.15s; }
.sl-lost-row:last-child { border-bottom:none; }
.sl-lost-row:hover { background:var(--surface2); }
.sl-lost-info { flex:1; min-width:0; }
.sl-lost-name { font-size:12px; font-weight:600; color:var(--text-1); }
.sl-lost-reason { font-family:'JetBrains Mono',monospace; font-size:10px; color:var(--c-rose); }
.sl-lost-amt { font-family:'JetBrains Mono',monospace; font-size:12px; font-weight:700; color:var(--text-2); flex-shrink:0; }

.sl-pulse { animation:sl-pulse-anim 1.4s ease-in-out infinite; }
@keyframes sl-pulse-anim { 0%,100% { opacity:1; } 50% { opacity:0.3; } }

script:
setTimeout(function () {

  var root = root_element;
  var currentPeriod = 'this_month';
  var dashData = {};
  var THEME_KEY = 'jagdamba_prod_dash_theme';

  var getDashEl = function () { return q('#jdProdDashboard') || root; };

  var applyTheme = function (t) {
    if (t === 'dark') getDashEl().classList.add('dark');
    else getDashEl().classList.remove('dark');
  };

  var toggleTheme = function () {
    var isDark = getDashEl().classList.contains('dark');
    var next = isDark ? 'light' : 'dark';
    applyTheme(next);
    try { localStorage.setItem(THEME_KEY, next); } catch (e) {}
  };

  var loadTheme = function () {
    try {
      var saved = localStorage.getItem(THEME_KEY);
      if (saved) { applyTheme(saved); return; }
    } catch (e) {}
    applyTheme('light');
  };

  var q  = function (s) { return root.querySelector(s); };
  var qa = function (s) { return root.querySelectorAll(s); };

  var setText = function (id, v) {
    var el = q('#' + id);
    if (el) el.textContent = (v !== null && v !== undefined) ? v : '—';
  };

  var fmtNum = function (val) {
    var num = parseFloat(val) || 0;
    return num.toLocaleString();
  };

  var setDate = function () {
    var el = q('#jdDate');
    if (el) el.textContent = new Date().toLocaleDateString('en-US', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric' });
  };

  var setLoading = function (on) {
    var ids = ['jd-so', 'jd-ocs', 'jd-design', 'jd-wo', 'jd-jc', 'jd-overdue'];
    ids.forEach(function (id) {
      var el = q('#' + id);
      if (!el) return;
      if (on) { el.textContent = '…'; el.classList.add('jd-pulse'); }
      else el.classList.remove('jd-pulse');
    });
  };

  var STAGE_CLASS = {
    'Lead / Quotation': 's-quote',
    'Sales Order': 's-so',
    'Order Confirmation': 's-ocs',
    'Design': 's-design',
    'Production': 's-prod',
    'Completed': 's-done'
  };

  var populateKPIs = function (d) {
    var p = d.pipeline_summary || {};
    setText('jd-so', fmtNum(p.sales_orders));
    setText('jd-ocs', fmtNum(p.ocs_open));
    setText('jd-design', fmtNum(p.designing_in_progress));
    setText('jd-wo', fmtNum(p.work_orders_open));
    setText('jd-jc', fmtNum(p.job_cards_open));
    setText('jd-overdue', fmtNum((d.overdue_job_cards || []).length));
    setText('jdPeriodLabel', d.period_label || '');
  };

  var populateVehicleTypes = function (rows) {
    var el = q('#jd-vt-row');
    if (!el) return;
    if (!rows || !rows.length) { el.innerHTML = '<div class="jd-loader">No sales orders yet</div>'; return; }
    el.innerHTML = rows.map(function (r) {
      return '<div class="jd-vt-card" data-vt="' + (r.vehicle_type || '') + '">' +
        '<span class="jd-vt-name">' + (r.vehicle_type || 'Unassigned') + '</span>' +
        '<span class="jd-vt-count">' + fmtNum(r.count) + '</span>' +
      '</div>';
    }).join('');
    el.querySelectorAll('.jd-vt-card').forEach(function (card) {
      card.addEventListener('click', function () {
        // Vehicle type lives on Quotation, not Sales Order directly
        frappe.set_route('List', 'Quotation', { custom_vehicle_type: card.dataset.vt });
      });
    });
  };

  var populatePipeline = function (rows) {
    var el = q('#jd-pipeline-list');
    if (!el) return;
    if (!rows || !rows.length) { el.innerHTML = '<div class="jd-loader">No active projects</div>'; return; }
    el.innerHTML = rows.map(function (r) {
      var cls = STAGE_CLASS[r.stage] || 's-quote';
      return '<div class="jd-pipeline-row" data-project="' + r.project + '">' +
        '<div><div class="jd-pipeline-project">' + (r.project_name || r.project) + '</div><div class="jd-pipeline-sub">' + r.project + '</div></div>' +
        '<div class="jd-pipeline-sub">' + (r.customer || '—') + '</div>' +
        '<div class="jd-pipeline-sub">' + (r.vehicle_type || '—') + '</div>' +
        '<div><span class="jd-stage-badge ' + cls + '">' + r.stage + '</span></div>' +
        '<div>' +
          (r.work_order
            ? ('<div class="jd-pipeline-sub">' + (r.wo_percent || 0) + '%</div><div class="jd-mini-bar-track"><div class="jd-mini-bar-fill" style="width:' + (r.wo_percent || 0) + '%"></div></div>')
            : '<span class="jd-pipeline-sub">—</span>') +
        '</div>' +
      '</div>';
    }).join('');
    el.querySelectorAll('.jd-pipeline-row').forEach(function (row) {
      row.addEventListener('click', function () { frappe.set_route('Form', 'Project', row.dataset.project); });
    });
  };

  var JC_COLUMN_ORDER = ['Open', 'Work In Progress', 'Material Transferred', 'On Hold', 'Completed'];

  var populateJobCardBoard = function (board, summary) {
    var el = q('#jd-jc-board');
    if (!el) return;
    if (!board || !Object.keys(board).length) {
      el.innerHTML = '<div class="jd-loader">No Job Cards found — Work Orders may not be raised yet</div>';
      return;
    }

    var columns = JC_COLUMN_ORDER.filter(function (s) { return board[s]; });
    Object.keys(board).forEach(function (s) { if (columns.indexOf(s) === -1) columns.push(s); });

    el.innerHTML = columns.map(function (status) {
      var cards = board[status] || [];
      var count = (summary && summary[status] !== undefined) ? summary[status] : cards.length;
      var body = cards.length
        ? cards.slice(0, 12).map(function (jc) {
            return '<div class="jd-jc-card" data-name="' + jc.name + '">' +
              '<div class="jd-jc-card-item">' + (jc.wo_item_name || jc.production_item || jc.work_order || '—') + '</div>' +
              '<div class="jd-jc-card-op">' + (jc.operation || '—') + (jc.workstation ? ' · ' + jc.workstation : '') + '</div>' +
              '<div class="jd-jc-card-meta">' + (jc.project_name || '') + (jc.expected_end_date ? ' · due ' + jc.expected_end_date : '') + '</div>' +
            '</div>';
          }).join('')
        : '<div class="jd-jc-empty">No cards</div>';

      return '<div class="jd-jc-col">' +
        '<div class="jd-jc-col-head"><span class="jd-jc-col-title">' + status + '</span><span class="jd-jc-col-count">' + count + '</span></div>' +
        '<div class="jd-jc-col-body">' + body + '</div>' +
      '</div>';
    }).join('');

    el.querySelectorAll('.jd-jc-card').forEach(function (card) {
      card.addEventListener('click', function () { frappe.set_route('Form', 'Job Card', card.dataset.name); });
    });
  };

  var populateWorkOrders = function (rows) {
    var el = q('#jd-wo-list');
    if (!el) return;
    if (!rows || !rows.length) { el.innerHTML = '<div class="jd-loader">No submitted Work Orders</div>'; return; }
    el.innerHTML = rows.slice(0, 8).map(function (wo) {
      return '<div class="jd-wo-row" data-name="' + wo.name + '">' +
        '<div class="jd-wo-info">' +
          '<div class="jd-wo-name">' + (wo.item_name || wo.production_item) + '</div>' +
          '<div class="jd-wo-sub">' + wo.name + ' · ' + (wo.status || '') + (wo.project_name ? ' · ' + wo.project_name : '') + '</div>' +
        '</div>' +
        '<div class="jd-wo-progress">' +
          '<div class="jd-wo-pct">' + (wo.percent_complete || 0) + '%</div>' +
          '<div class="jd-mini-bar-track"><div class="jd-mini-bar-fill" style="width:' + (wo.percent_complete || 0) + '%"></div></div>' +
        '</div>' +
      '</div>';
    }).join('');
    el.querySelectorAll('.jd-wo-row').forEach(function (row) {
      row.addEventListener('click', function () { frappe.set_route('Form', 'Work Order', row.dataset.name); });
    });
  };

  var populateOperationLoad = function (rows) {
    var el = q('#jd-op-load');
    if (!el) return;
    if (!rows || !rows.length) { el.innerHTML = '<div class="jd-loader">No active operations</div>'; return; }
    var max = Math.max.apply(null, rows.map(function (r) { return parseInt(r.job_count, 10) || 0; }));
    el.innerHTML = rows.slice(0, 8).map(function (r) {
      var pct = max > 0 ? Math.round((parseInt(r.job_count, 10) || 0) / max * 100) : 0;
      return '<div class="jd-op-row">' +
        '<div><div class="jd-op-name">' + (r.operation || 'Unspecified') + '</div><div class="jd-op-ws">' + (r.workstation || '—') + '</div></div>' +
        '<div class="jd-op-bar-wrap"><div class="jd-op-bar" style="width:' + pct + '%"></div></div>' +
        '<div class="jd-op-count">' + r.job_count + '</div>' +
      '</div>';
    }).join('');
  };

  var populateOverdue = function (rows) {
    var el = q('#jd-overdue-list');
    if (!el) return;
    if (!rows || !rows.length) { el.innerHTML = '<div class="jd-loader">Nothing overdue 🎉</div>'; return; }
    el.innerHTML = rows.map(function (jc) {
      var days = 0;
      try {
        var due = new Date(jc.expected_end_date);
        days = Math.round((new Date() - due) / 86400000);
      } catch (e) {}
      return '<div class="jd-overdue-row" data-name="' + jc.name + '">' +
        '<div class="jd-overdue-info">' +
          '<div class="jd-overdue-name">' + (jc.wo_item_name || jc.production_item || jc.name) + '</div>' +
          '<div class="jd-overdue-sub">' + jc.name + ' · ' + (jc.operation || '—') + ' · ' + (jc.workstation || '—') + '</div>' +
        '</div>' +
        '<span class="jd-overdue-days">' + days + 'd overdue</span>' +
      '</div>';
    }).join('');
    el.querySelectorAll('.jd-overdue-row').forEach(function (row) {
      row.addEventListener('click', function () { frappe.set_route('Form', 'Job Card', row.dataset.name); });
    });
  };

  var refresh = function () {
    var btn = q('#jdRefreshBtn');
    if (btn) btn.classList.add('spinning');
    setLoading(true);

    frappe.call({
      method: 'jagadamba.jagadamba.api.get_production_dashboard_data',
      args: { period: currentPeriod },
      callback: function (r) {
        if (btn) btn.classList.remove('spinning');
        setLoading(false);
        if (r.exc || !r.message) {
          frappe.msgprint({ title: 'Dashboard Error', message: 'Failed to load. Check console.', indicator: 'red' });
          console.error('Production Dashboard Error:', r.exc);
          return;
        }
        dashData = r.message;
        populateKPIs(dashData);
        populateVehicleTypes(dashData.vehicle_type_summary);
        populatePipeline(dashData.project_pipeline);
        populateJobCardBoard(dashData.job_card_board, dashData.job_card_summary);
        populateWorkOrders(dashData.work_orders);
        populateOperationLoad(dashData.operation_load);
        populateOverdue(dashData.overdue_job_cards);
      },
      error: function (r) {
        if (btn) btn.classList.remove('spinning');
        setLoading(false);
        console.error('Production Dashboard Error:', r);
      }
    });
  };

  var attachListeners = function () {
    var refreshBtn = q('#jdRefreshBtn');
    if (refreshBtn) refreshBtn.addEventListener('click', refresh);

    var themeBtn = q('#jdThemeBtn');
    if (themeBtn) themeBtn.addEventListener('click', toggleTheme);

    var periodSel = q('#jdPeriodSelect');
    if (periodSel) periodSel.addEventListener('change', function () { currentPeriod = this.value; refresh(); });

    ['jd-kpi-so', 'jd-kpi-wo'].forEach(function (id) {});

    var kpiSo = q('#jd-kpi-so');
    if (kpiSo) kpiSo.addEventListener('click', function () { frappe.set_route('List', 'Sales Order'); });
    var kpiOcs = q('#jd-kpi-ocs');
    if (kpiOcs) kpiOcs.addEventListener('click', function () { frappe.set_route('List', 'Order Confirmation Sheet'); });
    var kpiDesign = q('#jd-kpi-design');
    if (kpiDesign) kpiDesign.addEventListener('click', function () { frappe.set_route('List', 'Designing'); });
    var kpiWo = q('#jd-kpi-wo');
    if (kpiWo) kpiWo.addEventListener('click', function () { frappe.set_route('List', 'Work Order'); });
    var kpiJc = q('#jd-kpi-jc');
    if (kpiJc) kpiJc.addEventListener('click', function () { frappe.set_route('List', 'Job Card'); });
    var kpiOverdue = q('#jd-kpi-overdue');
    if (kpiOverdue) kpiOverdue.addEventListener('click', function () { frappe.set_route('List', 'Job Card'); });

    var linkWo = q('#jd-link-wo');
    if (linkWo) linkWo.addEventListener('click', function () { frappe.set_route('List', 'Work Order'); });
    var linkJc = q('#jd-link-jc');
    if (linkJc) linkJc.addEventListener('click', function () { frappe.set_route('List', 'Job Card'); });
  };

  loadTheme();
  setDate();
  attachListeners();
  refresh();

}, 1000);

style:
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500&display=swap');

.jd-dash {
  --bg: #f4f6fb;
  --surface: #ffffff;
  --surface2: #f7f9fd;
  --border: #e5e9f2;
  --border-md: #d0d7e8;
  --text-1: #111827;
  --text-2: #4b5675;
  --text-3: #9ca3b8;
  --c-emerald: #059669; --c-emerald-bg: #ecfdf5;
  --c-blue: #2563eb;    --c-blue-bg: #eff6ff;
  --c-amber: #d97706;   --c-amber-bg: #fffbeb;
  --c-rose: #e11d48;    --c-rose-bg: #fff1f2;
  --c-teal: #0d9488;    --c-teal-bg: #f0fdfa;
  --c-violet: #7c3aed;  --c-violet-bg: #f5f3ff;
  --shadow: 0 1px 4px rgba(17,24,39,0.06), 0 0 0 1px var(--border);
  --shadow-hover: 0 6px 20px rgba(17,24,39,0.1), 0 0 0 1px var(--border-md);
  --radius: 14px; --radius-sm: 9px;
  font-family: 'Plus Jakarta Sans', sans-serif;
  background: var(--bg);
  color: var(--text-1);
  padding: 24px 22px;
  min-height: 100vh;
  transition: background 0.3s, color 0.3s;
}

.jd-dash.dark {
  --bg: #0f1117; --surface: #161b26; --surface2: #1d2333;
  --border: #242c3f; --border-md: #2e3850;
  --text-1: #e8ecf5; --text-2: #7c8db0; --text-3: #4a5568;
  --c-emerald: #10b981; --c-emerald-bg: rgba(16,185,129,0.12);
  --c-blue: #3b82f6;    --c-blue-bg: rgba(59,130,246,0.12);
  --c-amber: #f59e0b;   --c-amber-bg: rgba(245,158,11,0.12);
  --c-rose: #f43f5e;    --c-rose-bg: rgba(244,63,94,0.12);
  --c-teal: #14b8a6;    --c-teal-bg: rgba(20,184,166,0.12);
  --c-violet: #8b5cf6;  --c-violet-bg: rgba(139,92,246,0.12);
  --shadow: 0 1px 4px rgba(0,0,0,0.35), 0 0 0 1px var(--border);
  --shadow-hover: 0 6px 24px rgba(0,0,0,0.4), 0 0 0 1px var(--border-md);
}

.jd-header { display:flex; align-items:center; justify-content:space-between; margin-bottom:22px; flex-wrap:wrap; gap:12px; }
.jd-eyebrow { font-family:'JetBrains Mono',monospace; font-size:10px; letter-spacing:0.2em; color:var(--c-teal); text-transform:uppercase; display:block; margin-bottom:4px; }
.jd-title { font-size:24px; font-weight:800; color:var(--text-1); margin:0; letter-spacing:-0.025em; line-height:1; }
.jd-header-right { display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
.jd-date { font-family:'JetBrains Mono',monospace; font-size:11px; color:var(--text-3); }

.jd-period-select { font-family:'Plus Jakarta Sans',sans-serif; font-size:12px; font-weight:500; background:var(--surface); border:1px solid var(--border-md); color:var(--text-2); padding:6px 10px; border-radius:7px; cursor:pointer; outline:none; }

.jd-btn { display:flex; align-items:center; gap:6px; background:var(--surface); border:1px solid var(--border-md); color:var(--text-2); font-family:'Plus Jakarta Sans',sans-serif; font-size:12px; font-weight:600; padding:6px 12px; border-radius:7px; cursor:pointer; transition:all 0.18s; }
.jd-btn:hover { border-color:var(--c-teal); color:var(--c-teal); }
.jd-btn.spinning svg { animation:jd-spin 0.6s linear infinite; }
@keyframes jd-spin { to { transform:rotate(360deg); } }

.jd-icon-sun,.jd-icon-moon { position:absolute; left:50%; top:50%; transition:transform 0.4s cubic-bezier(0.34,1.56,0.64,1),opacity 0.2s; }
.jd-icon-sun { opacity:1; transform:translate(-50%,-50%) rotate(0) scale(1); }
.jd-icon-moon { opacity:0; transform:translate(-50%,-50%) rotate(90deg) scale(0.5); }
.jd-dash.dark .jd-icon-sun { opacity:0; transform:translate(-50%,-50%) rotate(-90deg) scale(0.5); }
.jd-dash.dark .jd-icon-moon { opacity:1; transform:translate(-50%,-50%) rotate(0) scale(1); }
#jdThemeBtn { width:34px; height:32px; padding:0; position:relative; }

.jd-section-label { font-size:10px; font-weight:700; letter-spacing:0.12em; text-transform:uppercase; color:var(--text-3); margin:20px 0 10px; font-family:'JetBrains Mono',monospace; }

/* KPI row */
.jd-kpi-row { display:grid; grid-template-columns:repeat(6,minmax(0,1fr)); gap:12px; }
@media (max-width:1300px) { .jd-kpi-row { grid-template-columns:repeat(3,minmax(0,1fr)); } }
@media (max-width:700px)  { .jd-kpi-row { grid-template-columns:repeat(2,minmax(0,1fr)); } }

.jd-kpi { background:var(--surface); border-radius:var(--radius); box-shadow:var(--shadow); padding:16px; cursor:pointer; position:relative; overflow:hidden; transition:box-shadow 0.2s,transform 0.2s; }
.jd-kpi:hover { box-shadow:var(--shadow-hover); transform:translateY(-2px); }
.jd-kpi-accent { position:absolute; left:0; top:0; bottom:0; width:3px; }
.jd-kpi.blue .jd-kpi-accent    { background:var(--c-blue); }
.jd-kpi.amber .jd-kpi-accent   { background:var(--c-amber); }
.jd-kpi.violet .jd-kpi-accent  { background:var(--c-violet); }
.jd-kpi.teal .jd-kpi-accent    { background:var(--c-teal); }
.jd-kpi.emerald .jd-kpi-accent { background:var(--c-emerald); }
.jd-kpi.rose .jd-kpi-accent    { background:var(--c-rose); }
.jd-kpi-body { display:flex; flex-direction:column; gap:2px; }
.jd-kpi-label { font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:0.07em; color:var(--text-3); }
.jd-kpi-val { font-size:24px; font-weight:800; color:var(--text-1); letter-spacing:-0.025em; }
.jd-kpi-sub { font-family:'JetBrains Mono',monospace; font-size:10px; color:var(--text-3); margin-top:2px; }

/* Vehicle type cards */
.jd-vt-row { display:flex; flex-wrap:wrap; gap:10px; }
.jd-vt-card { background:var(--surface); border-radius:var(--radius-sm); box-shadow:var(--shadow); padding:12px 16px; min-width:140px; display:flex; flex-direction:column; gap:4px; cursor:pointer; transition:box-shadow 0.2s; }
.jd-vt-card:hover { box-shadow:var(--shadow-hover); }
.jd-vt-name { font-size:11px; font-weight:700; color:var(--text-2); text-transform:uppercase; letter-spacing:0.04em; }
.jd-vt-count { font-size:20px; font-weight:800; color:var(--c-teal); }

/* Panels */
.jd-panel { background:var(--surface); border-radius:var(--radius); box-shadow:var(--shadow); overflow:hidden; }
.jd-panel-header { display:flex; justify-content:space-between; align-items:center; padding:14px 16px; border-bottom:1px solid var(--border); background:var(--surface2); }
.jd-panel-title { font-size:12px; font-weight:700; color:var(--text-1); }
.jd-panel-link { font-size:11px; color:var(--c-blue); cursor:pointer; font-weight:600; text-decoration:none; }
.jd-panel-link:hover { opacity:0.65; }
.jd-panel-body { padding:6px 0; min-height:80px; }
.jd-loader { text-align:center; padding:30px; color:var(--text-3); font-family:'JetBrains Mono',monospace; font-size:11px; }

/* Pipeline table */
.jd-pipeline-head { display:grid; grid-template-columns:1.4fr 1.4fr 1fr 1fr 1fr; gap:0; padding:8px 16px; background:var(--surface2); border-bottom:1px solid var(--border); font-family:'JetBrains Mono',monospace; font-size:9px; font-weight:700; text-transform:uppercase; letter-spacing:0.06em; color:var(--text-3); }
.jd-pipeline-row { display:grid; grid-template-columns:1.4fr 1.4fr 1fr 1fr 1fr; gap:0; padding:10px 16px; border-bottom:1px solid var(--border); align-items:center; cursor:pointer; transition:background 0.15s; }
.jd-pipeline-row:last-child { border-bottom:none; }
.jd-pipeline-row:hover { background:var(--surface2); }
.jd-pipeline-project { font-size:12px; font-weight:600; color:var(--text-1); }
.jd-pipeline-sub { font-family:'JetBrains Mono',monospace; font-size:10px; color:var(--text-3); }
.jd-stage-badge { display:inline-block; font-family:'JetBrains Mono',monospace; font-size:9px; font-weight:700; padding:3px 8px; border-radius:5px; text-transform:uppercase; letter-spacing:0.03em; }
.jd-stage-badge.s-quote     { background:rgba(124,131,153,0.12); color:var(--text-2); }
.jd-stage-badge.s-so        { background:var(--c-blue-bg); color:var(--c-blue); }
.jd-stage-badge.s-ocs       { background:var(--c-amber-bg); color:var(--c-amber); }
.jd-stage-badge.s-design    { background:var(--c-violet-bg); color:var(--c-violet); }
.jd-stage-badge.s-prod      { background:var(--c-teal-bg); color:var(--c-teal); }
.jd-stage-badge.s-done      { background:var(--c-emerald-bg); color:var(--c-emerald); }
.jd-mini-bar-track { height:5px; background:var(--border); border-radius:3px; overflow:hidden; margin-top:3px; }
.jd-mini-bar-fill { height:100%; background:var(--c-teal); border-radius:3px; }

/* Job card kanban */
.jd-jc-board { display:grid; grid-template-columns:repeat(5,minmax(0,1fr)); gap:12px; align-items:start; }
@media (max-width:1100px) { .jd-jc-board { grid-template-columns:repeat(2,minmax(0,1fr)); } }
@media (max-width:600px)  { .jd-jc-board { grid-template-columns:1fr; } }

.jd-jc-col { background:var(--surface); border-radius:var(--radius); box-shadow:var(--shadow); overflow:hidden; }
.jd-jc-col-head { padding:10px 12px; border-bottom:1px solid var(--border); background:var(--surface2); display:flex; justify-content:space-between; align-items:center; }
.jd-jc-col-title { font-size:11px; font-weight:700; color:var(--text-1); }
.jd-jc-col-count { font-family:'JetBrains Mono',monospace; font-size:10px; color:var(--text-3); background:var(--border); padding:1px 7px; border-radius:10px; }
.jd-jc-col-body { max-height:340px; overflow-y:auto; padding:8px; display:flex; flex-direction:column; gap:6px; }
.jd-jc-card { background:var(--surface2); border:1px solid var(--border); border-radius:8px; padding:8px 10px; cursor:pointer; transition:border-color 0.15s; }
.jd-jc-card:hover { border-color:var(--c-teal); }
.jd-jc-card-item { font-size:11px; font-weight:600; color:var(--text-1); overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.jd-jc-card-op { font-family:'JetBrains Mono',monospace; font-size:9px; color:var(--c-teal); margin-top:2px; }
.jd-jc-card-meta { font-family:'JetBrains Mono',monospace; font-size:9px; color:var(--text-3); margin-top:3px; }
.jd-jc-empty { padding:16px; text-align:center; color:var(--text-3); font-family:'JetBrains Mono',monospace; font-size:10px; }

/* Two col */
.jd-two-col { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:12px; margin-top:20px; }
@media (max-width:900px) { .jd-two-col { grid-template-columns:1fr; } }

/* Work order rows */
.jd-wo-row { display:flex; align-items:center; padding:10px 16px; border-bottom:1px solid var(--border); gap:10px; cursor:pointer; transition:background 0.15s; }
.jd-wo-row:last-child { border-bottom:none; }
.jd-wo-row:hover { background:var(--surface2); }
.jd-wo-info { flex:1; min-width:0; }
.jd-wo-name { font-size:12px; font-weight:600; color:var(--text-1); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.jd-wo-sub { font-family:'JetBrains Mono',monospace; font-size:10px; color:var(--text-3); }
.jd-wo-progress { width:90px; flex-shrink:0; }
.jd-wo-pct { font-family:'JetBrains Mono',monospace; font-size:11px; color:var(--c-teal); text-align:right; margin-bottom:3px; }

/* Operation load */
.jd-op-row { display:flex; align-items:center; gap:10px; padding:9px 16px; border-bottom:1px solid var(--border); }
.jd-op-row:last-child { border-bottom:none; }
.jd-op-name { font-size:12px; font-weight:600; color:var(--text-1); min-width:110px; flex-shrink:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.jd-op-ws { font-family:'JetBrains Mono',monospace; font-size:9px; color:var(--text-3); }
.jd-op-bar-wrap { flex:1; height:6px; background:var(--border); border-radius:3px; overflow:hidden; }
.jd-op-bar { height:100%; background:var(--c-violet); border-radius:3px; }
.jd-op-count { font-family:'JetBrains Mono',monospace; font-size:11px; color:var(--text-2); min-width:26px; text-align:right; }

/* Overdue */
.jd-overdue-row { display:flex; align-items:center; gap:10px; padding:9px 16px; border-bottom:1px solid var(--border); cursor:pointer; transition:background 0.15s; }
.jd-overdue-row:last-child { border-bottom:none; }
.jd-overdue-row:hover { background:var(--surface2); }
.jd-overdue-info { flex:1; min-width:0; }
.jd-overdue-name { font-size:12px; font-weight:600; color:var(--text-1); }
.jd-overdue-sub { font-family:'JetBrains Mono',monospace; font-size:10px; color:var(--text-3); }
.jd-overdue-days { font-family:'JetBrains Mono',monospace; font-size:10px; font-weight:700; color:var(--c-rose); background:var(--c-rose-bg); padding:3px 8px; border-radius:5px; white-space:nowrap; }

.jd-pulse { animation:jd-pulse-anim 1.4s ease-in-out infinite; }
@keyframes jd-pulse-anim { 0%,100% { opacity:1; } 50% { opacity:0.3; } }
